CREATE TABLE gold.session_state (`session_month` Date CODEC(ZSTD(1)), `video_session_id` FixedString(64) CODEC(ZSTD(1)), `user_id` AggregateFunction(any, FixedString(64)) CODEC(ZSTD(1)), `content_id` AggregateFunction(any, Int64) CODEC(ZSTD(1)), `platform` AggregateFunction(any, LowCardinality(String)) CODEC(ZSTD(1)), `video_resolution` AggregateFunction(any, LowCardinality(String)) CODEC(ZSTD(1)), `country` AggregateFunction(any, LowCardinality(String)) CODEC(ZSTD(1)), `app_version` AggregateFunction(any, LowCardinality(String)) CODEC(ZSTD(1)), `audio_languages` AggregateFunction(groupUniqArray, String) CODEC(ZSTD(1)), `subtitle_languages` AggregateFunction(groupUniqArray, String) CODEC(ZSTD(1)), `player_version` AggregateFunction(any, LowCardinality(String)) CODEC(ZSTD(1)), `session_start_epoch` AggregateFunction(any, DateTime64(3, 'UTC')) CODEC(ZSTD(1)), `title` AggregateFunction(any, String) CODEC(ZSTD(1)), `video_type` AggregateFunction(any, String) CODEC(ZSTD(1)), `category` AggregateFunction(any, String) CODEC(ZSTD(1)), `show_name` AggregateFunction(any, String) CODEC(ZSTD(1)), `latest_event_type` AggregateFunction(argMax, String, DateTime64(3, 'UTC')) CODEC(ZSTD(1)), `latest_event` AggregateFunction(argMax, String, DateTime64(3, 'UTC')) CODEC(ZSTD(1)), `last_event_ts` SimpleAggregateFunction(max, DateTime64(3, 'UTC')) CODEC(DoubleDelta, ZSTD(1)), `is_active` AggregateFunction(argMax, UInt8, DateTime64(3, 'UTC')) CODEC(ZSTD(1))) ENGINE = SharedAggregatingMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(session_month) ORDER BY video_session_id SETTINGS index_granularity = 8192